    summary: "\u8BE5\u54C1\u724C\u5177\u5907\u4EA7\u54C1\u548C\u4EA7\u5730\u6545\u4E8B\uFF0C\u4F46\u7EBF\u4E0A\u5E97\u94FA\u7F3A\u5C11\u6E05\u6670\u8868\u8FBE\u548C\u6210\u4EA4\u8DEF\u5F84\u3002\u54C1\u6C90\u4ECE\u5E97\u94FA\u89C6\u89C9\u3001\u5546\u54C1\u7ED3\u6784\u3001\u4E3B\u56FE\u8BE6\u60C5\u9875\u3001\u4EF7\u683C\u5E26\u548C\u5E73\u53F0\u8282\u594F\u5165\u624B\uFF0C\u68B3\u7406\u4F18\u5316\u65B9\u5411\u3002",
    background: "\u5BA2\u6237\u4E3A\u5730\u65B9\u7279\u8272\u9152\u6C34\u54C1\u724C\uFF0C\u5177\u5907\u4EA7\u54C1\u8D44\u6E90\u3001\u4EA7\u5730\u6545\u4E8B\u548C\u793C\u8D60\u573A\u666F\uFF0C\u4F46\u7EBF\u4E0A\u5E97\u94FA\u7ECF\u8425\u57FA\u7840\u8F83\u5F31\u3002\u54C1\u724C\u5E0C\u671B\u901A\u8FC7\u7535\u5546\u6E20\u9053\u6253\u5F00\u66F4\u591A\u9500\u552E\u673A\u4F1A\uFF0C\u4F46\u4E0D\u786E\u5B9A\u5F53\u524D\u95EE\u9898\u4E3B\u8981\u51FA\u5728\u4EA7\u54C1\u3001\u9875\u9762\u3001\u6D41\u91CF\u8FD8\u662F\u4EF7\u683C\u4F53\u7CFB\u3002",
