      basis: "\u54C1\u724C\u5B98\u7F51\u3001\u516C\u53F8\u4E0E\u54C1\u724C\u516C\u5F00\u8D44\u6599\u3001\u4EA7\u54C1\u6807\u7B7E\u4E0E\u8BF4\u660E\u3001\u4EA7\u533A\u6216\u68C0\u6D4B\u76F8\u5173\u53EF\u516C\u5F00\u6587\u4EF6\u3001\u5E73\u53F0\u5546\u54C1\u9875\u3001\u5BA2\u670D\u95EE\u9898\u548C\u54C1\u724C\u65B9\u6388\u6743\u7684\u7ECF\u8425\u6570\u636E\u3002",
      scope: "\u9002\u7528\u4E8E\u65B0\u4F1A\u9648\u76AE\u53CA\u76F8\u5173\u8336\u996E\u98DF\u54C1\u54C1\u724C\u7684\u5B98\u7F51\u5185\u5BB9\u3001\u8D27\u67B6\u7535\u5546\u3001\u5185\u5BB9\u79CD\u8349\u3001\u5546\u54C1\u627F\u63A5\u548C AI \u641C\u7D22\u53EF\u89C1\u5EA6\u5EFA\u8BBE\u3002",
