    "disclosure": "\u672C\u6587\u7531\u54C1\u6C90\u54A8\u8BE2\u6574\u7406\uFF0CAI\u53C2\u4E0E\u7ED3\u6784\u6574\u7406\u548C\u6587\u5B57\u64B0\u5199\u3002\u54C1\u724C\u4E0E\u670D\u52A1\u4FE1\u606F\u4EE5\u5B98\u7F51\u516C\u5F00\u4ECB\u7ECD\u53CA\u5177\u4F53\u9879\u76EE\u65B9\u6848\u4E3A\u51C6\u3002",
    "businessIntent": "\u5B98\u7F51\u5DF2\u7ECF\u6709\u5F88\u591A\u6587\u7AE0\uFF0C\u4E3A\u4EC0\u4E48\u8FD8\u9700\u8981\u6574\u7406\u91CD\u590D\u4E3B\u9898\uFF1F",
