    "lead": [
      "\u6587\u7AE0\u6570\u91CF\u589E\u52A0\u540E\uFF0C\u54C1\u724C\u9700\u8981\u68C0\u67E5\u6BCF\u4E2A\u9875\u9762\u662F\u5426\u56DE\u7B54\u4E86\u4E0D\u540C\u95EE\u9898\uFF0C\u4EE5\u53CA\u65E7\u5185\u5BB9\u662F\u5426\u4E0E\u5F53\u524D\u670D\u52A1\u4E00\u81F4\u3002\u4E3B\u9898\u91CD\u590D\u4F1A\u589E\u52A0\u7EF4\u62A4\u6210\u672C\uFF0C\u4E5F\u53EF\u80FD\u8BA9\u8BFB\u8005\u96BE\u4EE5\u627E\u5230\u771F\u6B63\u9700\u8981\u7684\u7B54\u6848\u3002",
      "\u5BA2\u6237\u641C\u7D22\u540C\u4E00\u4E2A\u95EE\u9898\uFF0C\u8FDB\u5165\u51E0\u7BC7\u6807\u9898\u76F8\u4F3C\u7684\u6587\u7AE0\uFF0C\u5F00\u5934\u548C\u7ED3\u5C3E\u51E0\u4E4E\u4E00\u6837\u3002\u8BFB\u5B8C\u4E4B\u540E\uFF0C\u4ED6\u4ECD\u7136\u4E0D\u77E5\u9053\u54EA\u7BC7\u66F4\u5B8C\u6574\uFF0C\u4E5F\u4E0D\u77E5\u9053\u54EA\u4E9B\u5EFA\u8BAE\u9002\u5408\u81EA\u5DF1\u3002"
    ],
    "sections": [
      {
        "id": "section-1",
        "title": "\u5148\u7ED9\u6BCF\u7BC7\u6587\u7AE0\u4E00\u4E2A\u660E\u786E\u7684\u4EFB\u52A1",
        "paragraphs": [
          "\u53EF\u4EE5\u6309\u5BA2\u6237\u95EE\u9898\u6574\u7406\u6587\u7AE0\u3002\u54C1\u724C\u4ECB\u7ECD\u3001\u670D\u52A1\u9009\u62E9\u3001\u62A5\u4EF7\u3001\u6267\u884C\u548C\u590D\u76D8\u5206\u522B\u670D\u52A1\u4E0D\u540C\u9636\u6BB5\u3002\u82E5\u4E24\u7BC7\u6587\u7AE0\u7684\u95EE\u9898\u3001\u5BF9\u8C61\u548C\u5EFA\u8BAE\u90FD\u76F8\u540C\uFF0C\u5C31\u503C\u5F97\u8BA8\u8BBA\u662F\u5426\u5408\u5E76\u6216\u66F4\u65B0\u3002",
          "\u6807\u9898\u4E0D\u540C\u5E76\u4E0D\u5FC5\u7136\u5F62\u6210\u65B0\u5185\u5BB9\u3002\u540C\u4E00\u4E2A\u6846\u67B6\u6362\u4E00\u4E2A\u5E74\u4EFD\u6216\u57CE\u5E02\uFF0C\u6B63\u6587\u6CA1\u6709\u65B0\u589E\u6761\u4EF6\u3001\u65B9\u6CD5\u6216\u4E8B\u5B9E\uFF0C\u8BFB\u8005\u83B7\u5F97\u7684\u4FE1\u606F\u4ECD\u7136\u6709\u9650\u3002\u9009\u9898\u5E94\u5F53\u4F53\u73B0\u771F\u5B9E\u7684\u5224\u65AD\u5DEE\u5F02\u3002",
          "\u6574\u7406\u65F6\u53EF\u4EE5\u8BB0\u5F55\u6BCF\u7BC7\u6587\u7AE0\u7684\u6838\u5FC3\u95EE\u9898\u3001\u670D\u52A1\u5BF9\u8C61\u3001\u6765\u6E90\u3001\u66F4\u65B0\u65F6\u95F4\u4E0E\u7EF4\u62A4\u4EBA\u3002\u65B0\u8D44\u6599\u51FA\u73B0\u540E\uFF0C\u56E2\u961F\u80FD\u627E\u5230\u9700\u8981\u4FEE\u6539\u7684\u9875\u9762\uFF1B\u670D\u52A1\u8303\u56F4\u53D8\u5316\u540E\uFF0C\u4E5F\u66F4\u5BB9\u6613\u53D1\u73B0\u54EA\u4E9B\u5916\u90E8\u7A3F\u4EF6\u9700\u8981\u540C\u6B65\u3002\u8FD9\u4E2A\u7D22\u5F15\u670D\u52A1\u5185\u5BB9\u7EF4\u62A4\uFF0C\u4E0D\u5FC5\u53D8\u6210\u6587\u7AE0\u4E2D\u53CD\u590D\u51FA\u73B0\u7684\u7EDF\u4E00\u6A21\u677F\u3002",
          "\u6709\u4E9B\u6587\u7AE0\u770B\u4F3C\u63A5\u8FD1\uFF0C\u5374\u5173\u6CE8\u4E0D\u540C\u4EFB\u52A1\u3002\u4F8B\u5982\uFF0C\u9996\u6B21\u6C9F\u901A\u8D44\u6599\u4E0E\u6B63\u5F0F\u8BCA\u65AD\u8D44\u6599\u53EF\u4EE5\u5206\u522B\u5199\uFF0C\u4F46\u9700\u8981\u660E\u786E\u5404\u81EA\u8303\u56F4\uFF0C\u907F\u514D\u91CD\u590D\u7C98\u8D34\u540C\u4E00\u4EFD\u6E05\u5355\u3002"
        ]
      },
      {
        "id": "section-2",
        "title": "\u66F4\u65B0\u65F6\u517C\u987E\u5DF2\u7ECF\u5B58\u5728\u7684\u8BBF\u95EE\u8DEF\u5F84",
        "paragraphs": [
          "\u5982\u679C\u51B3\u5B9A\u5408\u5E76\u9875\u9762\uFF0C\u53EF\u4EE5\u5148\u786E\u8BA4\u54EA\u7BC7\u9002\u5408\u4F5C\u4E3A\u5B8C\u6574\u5165\u53E3\uFF0C\u518D\u5904\u7406\u5176\u4ED6\u9875\u9762\u4E0E\u7AD9\u5185\u94FE\u63A5\u3002\u65E7\u5730\u5740\u53EF\u80FD\u4ECD\u88AB\u7528\u6237\u6216\u5916\u90E8\u6587\u7AE0\u8BBF\u95EE\uFF0C\u4E0D\u80FD\u53EA\u5220\u9664\u6B63\u6587\u800C\u4E0D\u8003\u8651\u8DEF\u5F84\u3002",
          "\u4FDD\u7559\u7684\u6587\u7AE0\u9700\u8981\u6838\u5BF9\u65E5\u671F\u3001\u6765\u6E90\u3001\u670D\u52A1\u8FB9\u754C\u548C\u76F8\u5173\u94FE\u63A5\u3002\u65B0\u589E\u4FE1\u606F\u5E94\u8FDB\u5165\u8BFB\u8005\u5B9E\u9645\u770B\u5230\u7684\u6B63\u6587\uFF0C\u800C\u4E0D\u662F\u53EA\u5728\u6807\u9898\u4E0A\u6807\u6CE8\u66F4\u65B0\u3002\u6D89\u53CA\u7F51\u7AD9\u8FC1\u79FB\u6216\u8DF3\u8F6C\u65F6\uFF0C\u8FD8\u9700\u6309\u5177\u4F53\u6280\u672F\u6761\u4EF6\u5904\u7406\u3002",
          "\u54C1\u724C\u53EF\u4EE5\u5C06\u5185\u5BB9\u7EF4\u62A4\u8BB0\u5F55\u7559\u5728\u5185\u90E8\uFF0C\u516C\u5F00\u9875\u9762\u53EA\u5448\u73B0\u8BFB\u8005\u9700\u8981\u7684\u8BF4\u660E\u3002\u8BFB\u8005\u5173\u5FC3\u7684\u662F\u5F53\u524D\u95EE\u9898\u6709\u6CA1\u6709\u88AB\u56DE\u7B54\uFF0C\u4E0D\u9700\u8981\u5728\u6587\u7AE0\u4E2D\u9605\u8BFB\u6BCF\u4E00\u6B65\u5185\u90E8\u68C0\u67E5\u6D41\u7A0B\u3002"
        ]
      },
      {
        "id": "section-3",
        "title": "\u65B0\u6587\u7AE0\u4ECE\u65B0\u7684\u95EE\u9898\u5F00\u59CB",
        "paragraphs": [
          "\u540E\u7EED\u9009\u9898\u53EF\u4EE5\u6765\u81EA\u5BA2\u670D\u3001\u54A8\u8BE2\u3001\u552E\u540E\u4E0E\u5B9E\u9645\u5F15\u7528\u8BB0\u5F55\u3002\u5BA2\u6237\u63D0\u51FA\u4E86\u65B0\u7684\u4F7F\u7528\u6761\u4EF6\uFF0C\u9879\u76EE\u51FA\u73B0\u4E86\u4E0D\u540C\u534F\u4F5C\u95EE\u9898\uFF0C\u624D\u6709\u673A\u4F1A\u5F62\u6210\u503C\u5F97\u5355\u72EC\u5199\u7684\u5185\u5BB9\u3002",
          "\u6BCF\u6B21\u65B0\u589E\u524D\uFF0C\u5148\u5230\u5DF2\u6709\u6587\u7AE0\u5E93\u67E5\u770B\u662F\u5426\u5DF2\u7ECF\u8986\u76D6\u3002\u9700\u8981\u8865\u5145\u7684\u5185\u5BB9\u53EF\u4EE5\u8FDB\u5165\u539F\u9875\u9762\uFF1B\u80FD\u591F\u72EC\u7ACB\u5C55\u5F00\u7684\u95EE\u9898\uFF0C\u518D\u5EFA\u7ACB\u65B0\u6587\u7AE0\uFF0C\u5E76\u63D0\u4F9B\u5FC5\u8981\u7684\u5EF6\u4F38\u9605\u8BFB\u3002",
          "\u6587\u7AE0\u5E93\u7684\u4EF7\u503C\uFF0C\u4F1A\u968F\u7740\u6E05\u695A\u7684\u4E3B\u9898\u5173\u7CFB\u4E0E\u6301\u7EED\u66F4\u65B0\u79EF\u7D2F\u3002\u8BA9\u8BFB\u8005\u66F4\u5BB9\u6613\u627E\u5230\u7B54\u6848\uFF0C\u6BD4\u8BA9\u5217\u8868\u4E0D\u65AD\u53D8\u957F\u66F4\u6709\u7ECF\u8425\u610F\u4E49\u3002"
        ]
      }
    ],
    "conclusion": "\u6587\u7AE0\u5E93\u7684\u4EF7\u503C\uFF0C\u4F1A\u968F\u7740\u6E05\u695A\u7684\u4E3B\u9898\u5173\u7CFB\u4E0E\u6301\u7EED\u66F4\u65B0\u79EF\u7D2F\u3002\u8BA9\u8BFB\u8005\u66F4\u5BB9\u6613\u627E\u5230\u7B54\u6848\uFF0C\u6BD4\u8BA9\u5217\u8868\u4E0D\u65AD\u53D8\u957F\u66F4\u6709\u7ECF\u8425\u610F\u4E49\u3002",
